fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0L) return "--"
    val seconds = exposureTimeNs / 1_000_000_000.0
    return if (seconds >= 0.1) {
        val rounded = Math.round(seconds * 10.0) / 10.0
        if (rounded % 1.0 == 0.0) {
            "${rounded.toLong()}s"
        } else {
            String.format("%.1f", rounded) + "s"
        }
    } else {
        "1/${(1.0 / seconds).roundToInt()}s"
    }
}

