lines = open('source.kt').readlines()
out = []
for line in lines:
    in_str = in_char = False
    i = 0
    strip_from = None
    while i < len(line):
        c = line[i]
        if in_str:
            if c == '\\':
                i += 2
                continue
            if c == '"':
                in_str = False
        elif in_char:
            if c == '\\':
                i += 2
                continue
            if c == "'":
                in_char = False
        else:
            if c == '"':
                in_str = True
            elif c == "'":
                in_char = True
            elif c == '/' and i + 1 < len(line) and line[i+1] == '/':
                strip_from = i
                break
            elif c == '/' and i + 1 < len(line) and line[i+1] == '*':
                raise SystemExit('BLOCK COMMENT FOUND: ' + line)
        i += 1
    if strip_from is None:
        out.append(line)
    else:
        code = line[:strip_from].rstrip()
        if code == '':
            continue  # pure comment line, drop it
        out.append(code + '\n')
open('source.kt', 'w').writelines(out)
print('done, lines:', len(out))
EOF

